private GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){ 
    List<E> edges = new ArrayList<>(tour); 
    Collections.sort(edges, Comparator.comparingInt(edge -> edge.hashCode())); 
    DefaultGraphPath<V, E> graphPath = new DefaultGraphPath<>(graph, true); 
    V previousVertex = null; 
    for (E edge : edges){ 
        E reverseEdge = graph.getEdge(edge.getTargetVertex(), edge.getSourceVertex()); 
        if (reverseEdge != null && tour.contains(reverseEdge)){ 
            edges.remove(reverseEdge); 
            continue; 
        } 
        if (previousVertex == null){ 
            previousVertex = edge.getSourceVertex(); 
            graphPath.addVertex(previousVertex); 
        } 
        graphPath.addEdge(previousVertex, edge); 
        previousVertex = edge.getTargetVertex(); 
    } 
    return graphPath; 
}

